<template>
    <div
        class="modal fade"
        id="erpBackupModal"
        tabindex="-1"
        aria-labelledby="erpBackupModalLabel"
        aria-hidden="true"
    >
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">

                <div class="modal-header">
                    <h5 class="modal-title" id="erpBackupModalLabel">
                        ERP Database Backup
                    </h5>
                    <button type="button" class="btn-close" @click="closeModal"></button>
                </div>

                <div class="modal-body">
                    <p class="mb-3">
                        This will download the entire ERP database.
                        Do you want to continue?
                    </p>

                    <div v-if="downloading">
                        <div class="progress" style="height: 20px;">
                            <div
                                class="progress-bar progress-bar-striped progress-bar-animated"
                                :style="{ width: progress + '%' }"
                            >
                                {{ progress }}%
                            </div>
                        </div>
                        <small class="text-muted d-block mt-1" v-if="totalSizeKnown">
                            {{ formatBytes(loadedBytes) }} / {{ formatBytes(totalBytes) }}
                        </small>
                    </div>
                </div>

                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @click="closeModal" :disabled="downloading">
                        Cancel
                    </button>

                    <button
                        type="button"
                        class="btn btn-primary"
                        :disabled="downloading"
                        @click="downloadBackup"
                    >
                        {{ downloading ? 'Downloading...' : 'Download Backup' }}
                    </button>
                </div>

            </div>
        </div>
    </div>
</template>

<script setup>
import { onMounted, onBeforeUnmount, ref, inject } from 'vue'
import axios from 'axios'
import { Modal } from 'bootstrap'

const showError = inject('showError')

const axiosInstance = axios.create({
    baseURL: process.env.VUE_APP_API_BASE_URL
})

const downloading = ref(false)
const progress = ref(0)
const loadedBytes = ref(0)
const totalBytes = ref(0)
const totalSizeKnown = ref(false)

let modalInstance = null

onMounted(() => {
    const modalElement = document.getElementById('erpBackupModal')
    if (modalElement) {
        modalInstance = Modal.getOrCreateInstance(modalElement)
        modalInstance.show()
        modalElement.addEventListener('hidden.bs.modal', closeModal)
    }
})

const closeModal = () => {
    if (modalInstance) modalInstance.hide()
    window.history.back()
}

const formatBytes = (bytes) => {
    if (!bytes) return '0 KB'
    const mb = bytes / (1024 * 1024)
    return mb >= 1 ? `${mb.toFixed(1)} MB` : `${(bytes / 1024).toFixed(0)} KB`
}

const downloadBackup = async () => {
    downloading.value = true
    progress.value = 0
    loadedBytes.value = 0
    totalSizeKnown.value = false

    try {
        const response = await axiosInstance.get('/database/export', {
            responseType: 'blob',
            onDownloadProgress: (e) => {
                loadedBytes.value = e.loaded
                if (e.total) {
                    totalBytes.value = e.total
                    totalSizeKnown.value = true
                    progress.value = Math.round((e.loaded / e.total) * 100)
                } else {
                    progress.value = Math.min(95, progress.value + 5)
                }
            }
        })

        const blobUrl = URL.createObjectURL(response.data)
        const link = document.createElement('a')
        link.href = blobUrl
        link.download = 'erp_database_backup.sql'
        document.body.appendChild(link)
        link.click()
        document.body.removeChild(link)
        URL.revokeObjectURL(blobUrl)

        progress.value = 100
    } catch (error) {
        showError(error.message)
    } finally {
        setTimeout(() => {
            downloading.value = false
        }, 500)
    }
}

onBeforeUnmount(() => {
    if (modalInstance) modalInstance.dispose()
})
</script>